from PIL import Image
from io import BytesIO
import pytest

from tracim_backend.lib.utils.image_process import ImageRatio
from tracim_backend.lib.utils.image_process import crop_image
from tracim_backend.tests.utils import create_png_test_image

# Minimal SVG matching the format generated by UserApi._get_default_avatar()
DEFAULT_AVATAR_SVG = (
    b'<svg viewBox="0 0 100 100" width="100%" height="100%"'
    b' xmlns="http://www.w3.org/2000/svg">'
    b'<circle cx="50%" cy="50%" r="50%" fill="#aabbcc"/>'
    b'<text fill="#fdfdfd" font-size="50" x="50" y="65" text-anchor="middle">AB</text>'
    b"</svg>"
)


class TestImageProcess(object):
    @pytest.mark.parametrize(
        "original_size, destination_size, ratio",
        [
            # original_size, destination_size, ratio
            # same ration
            ((300, 100), (300, 100), (3, 1)),
            ((600, 100), (600, 100), (6, 1)),
            ((100, 800), (100, 800), (1, 8)),
            ((100, 800), (100, 800), (2, 16)),
            ((256, 256), (256, 256), (1, 1)),
            # bigger original ratio
            ((300, 100), (200, 100), (2, 1)),
            ((600, 100), (300, 100), (3, 1)),
            ((50, 10), (2, 10), (1, 5)),
            # lower original ratio
            ((100, 100), (100, 50), (2, 1)),
            ((100, 100), (100, 33), (3, 1)),
            ((50, 200), (50, 10), (5, 1)),
            # edge cases
            ((12414, 4157), (12414, 1418), (35, 4)),
            ((626, 939), (626, 626), (1, 1)),
            ((100, 1), (1, 1), (1, 100)),
            # cover example
            ((100, 10), (87, 10), (35, 4)),
            ((1000, 100), (875, 100), (35, 4)),
        ],
    )
    def test__crop_image__nominal_case(self, original_size, destination_size, ratio):
        dest_image = BytesIO()
        original_image = create_png_test_image(*original_size)
        ratio = ImageRatio(*ratio)
        crop_image(original_image, dest_image, ratio=ratio)
        img = Image.open(dest_image)
        assert destination_size == img.size

    def test__crop_image__svg_input(self):
        # For the update to Debian 13 + Python 3.13 we updated Imagemagick to v7 (libmagickcore in system_packages/debian/run_backend_packages.list)
        # Since then when generating the DB on first run we have some warnings produced on stderr:
        # "Document is empty" / "ink_file_open: cannot be opened"
        # The conversion succeeds nevertheless...
        # This test reproduces those warnings and should produce on stderr:
        # ERROR: not found: /home/pierre/Code/Tracim/tracim_github/.claude/worktrees/feat+6859_debian-13_python-3.13/backend/tracim_backend/tests/library/test_image_process.py::test__crop_image__svg_input
        # (no name '/home/pierre/Code/Tracim/tracim_github/.claude/worktrees/feat+6859_debian-13_python-3.13/backend/tracim_backend/tests/library/test_image_process.py::test__crop_image__svg_input' in any of [<Module test_image_process.py>])
        dest_image = BytesIO()
        crop_image(BytesIO(DEFAULT_AVATAR_SVG), dest_image, ratio=ImageRatio(1, 1))
        img = Image.open(dest_image)
        assert img.size == (100, 100)
